# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN\'IN TEMEL KAVRAMLARI: İSLAM · TAKVA · SABIR · SULH</text>\n  <rect x="15" y="45" width="160" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="95" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. İSLAM (الْإِسْلَامُ)</text>\n  <text x="95" y="92" text-anchor="middle" font-size="10" fill="#1e3a8a">• Kökü: Silm / Selâm</text>\n  <text x="95" y="110" text-anchor="middle" font-size="10" fill="#1e3a8a">• Sözlük: Barış, esenlik,</text>\n  <text x="95" y="126" text-anchor="middle" font-size="10" fill="#1e3a8a">güven, boyun eğme</text>\n  <text x="95" y="148" text-anchor="middle" font-size="10" fill="#1e3a8a">• Terim: Allah\'ın birliğini</text>\n  <text x="95" y="164" text-anchor="middle" font-size="10" fill="#1e3a8a">kabul edip Hz. Muhammed\'in</text>\n  <text x="95" y="180" text-anchor="middle" font-size="10" fill="#1e3a8a">getirdiklerine teslim olma</text>\n  <text x="95" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Kişi: Müslim (الْمُسْلِمُ)</text>\n  <text x="95" y="222" text-anchor="middle" font-size="9" fill="#334155">Elinden-dilinden emin olunan</text>\n\n  <rect x="185" y="45" width="160" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="265" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. TAKVA (التَّقْوَى)</text>\n  <text x="265" y="92" text-anchor="middle" font-size="10" fill="#14532d">• Kökü: Vikâye (korunma)</text>\n  <text x="265" y="110" text-anchor="middle" font-size="10" fill="#14532d">• Sözlük: Sakınmak, korunmak,</text>\n  <text x="265" y="126" text-anchor="middle" font-size="10" fill="#14532d">saygı duymak</text>\n  <text x="265" y="148" text-anchor="middle" font-size="10" fill="#14532d">• Terim: Allah\'a karşı</text>\n  <text x="265" y="164" text-anchor="middle" font-size="10" fill="#14532d">sorumluluk bilinciyle emirleri</text>\n  <text x="265" y="180" text-anchor="middle" font-size="10" fill="#14532d">yapıp günahlardan kaçınma</text>\n  <text x="265" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Kişi: Müttaki (الْمُتَّقِي)</text>\n  <text x="265" y="222" text-anchor="middle" font-size="9" fill="#166534">Üstünlük takva iledir (Hucurât 13)</text>\n\n  <rect x="355" y="45" width="160" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="435" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. SABIR (الصَّبْرُ)</text>\n  <text x="435" y="92" text-anchor="middle" font-size="10" fill="#713f12">• Sözlük: Tutmak, engellemek,</text>\n  <text x="435" y="108" text-anchor="middle" font-size="10" fill="#713f12">tahammül ve direnç</text>\n  <text x="435" y="130" text-anchor="middle" font-size="10" fill="#713f12">• Üç Boyutu:</text>\n  <text x="435" y="148" text-anchor="middle" font-size="10" fill="#713f12">1. Musibetlere dayanma</text>\n  <text x="435" y="164" text-anchor="middle" font-size="10" fill="#713f12">2. İbadetlerde devamlılık</text>\n  <text x="435" y="180" text-anchor="middle" font-size="10" fill="#713f12">3. Günahlara karşı direnme</text>\n  <text x="435" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#a16207">Kişi: Sâbir (الصَّابِرُ)</text>\n  <text x="435" y="222" text-anchor="middle" font-size="9" fill="#854d0e">Allah sabredenlerle beraberdir</text>\n\n  <rect x="525" y="45" width="160" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="605" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">4. SULH (الصُّلْحُ)</text>\n  <text x="605" y="92" text-anchor="middle" font-size="10" fill="#581c87">• Kökü: Salâh (düzelme)</text>\n  <text x="605" y="110" text-anchor="middle" font-size="10" fill="#581c87">• Sözlük: Barış, uzlaşma,</text>\n  <text x="605" y="126" text-anchor="middle" font-size="10" fill="#581c87">kırgınlığı giderme</text>\n  <text x="605" y="148" text-anchor="middle" font-size="10" fill="#581c87">• Terim: İnsanlar ve</text>\n  <text x="605" y="164" text-anchor="middle" font-size="10" fill="#581c87">toplumlar arasındaki</text>\n  <text x="605" y="180" text-anchor="middle" font-size="10" fill="#581c87">anlaşmazlıkları barışla çözme</text>\n  <text x="605" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">İslâh: Aralarını düzeltme</text>\n  <text x="605" y="222" text-anchor="middle" font-size="9" fill="#6b21a8">"Sulh daha hayırlıdır" (Nisâ 128)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TECVİT KURALLARI: MEDD-İ TABİİ (ASLİ MED) VE SEBEB-İ MED</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Medd-i Tabii (الْمَدُّ الطَّبِيعِيُّ — Asli Med)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#164e63">• Med harfleri 3 tanedir: ا (Elif) · و (Vav) · ي (Yâ)</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#164e63">• Kural: Med harfinden sonra SEBEB-İ MED</text>\n  <text x="180" y="134" text-anchor="middle" font-size="11" fill="#164e63">(hemze veya sükûn) gelmezse Medd-i Tabii olur.</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">• Uzatma Miktarı: 1 Elif miktarı (2 hareke)</text>\n  <text x="180" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">Örnekler: قَالَ (Elif) · يَقُولُ (Vav) · قِيلَ (Yâ)</text>\n  <text x="180" y="206" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">نُوحِيهَا (3 med harfi bir kelimede: و - ي - ا)</text>\n  <text x="180" y="226" text-anchor="middle" font-size="10" fill="#164e63">Üstün + Elif · Ötre + Sakin Vav · Esre + Sakin Yâ</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Sebeb-i Med (Fer\'î Med Sebepleri)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#881337">Bir kelimeyi 1 eliften fazla uzatma sebebidir:</text>\n  <text x="520" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">1. HEMZE (الْهَمْزَةُ): ء (Kırık) veya أ / إ / آ (Uzun)</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11" fill="#881337">→ Medd-i Muttasıl ve Medd-i Munfasıl oluşturur.</text>\n  <text x="520" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">2. SÜKÛN (السُّكُونُ): Cezim (ْ) veya Şedde (ّ)</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" fill="#881337">→ Medd-i Lâzım ve Medd-i Ârız oluşturur.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Med İşareti (~): Uzatılacak harfin üzerine konur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MEDD-İ MUTTASIL (BİTİŞİK MED) VE MEDD-İ MUNFASIL (AYRIK MED)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Medd-i Muttasıl (الْمَدُّ الْمُتَّصِلُ — Bitişik)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#78350f">• Harf-i med ile sebeb-i med olan HEMZE (ء)</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">AYNI KELİME İÇİNDE yan yana gelirse oluşur.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#78350f">• Genellikle kırık hemze (ء) ile yazılır.</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">• Hükmü: VACİPTİR (4 elif / en az 2 elif uzatılır).</text>\n  <text x="180" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">Örnekler: جَاءَ · السَّمَاءِ · سُوءَ · المَلَائِكَةُ · شَاءَ</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#92400e">İpucu: Med harfi ve hemze tek kelimede bitişiktir.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Medd-i Munfasıl (الْمَدُّ الْمُنْفَصِلُ — Ayrık)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Harf-i med birinci kelimenin SONUNDA, hemze (أ/إ)</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">ikinci kelimenin BAŞINDA (ayrı kelimelerde) gelir.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#14532d">• Genellikle uzun hemze (elif: أ / إ) ile başlar.</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Hükmü: CAİZDİR (Hızlı okumada 1-2, yavaşta 4 elif).</text>\n  <text x="520" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Örnekler: يَا أَيُّهَا · إِنَّا أَعْطَيْنَاكَ · قُوا أَنْفُسَكُمْ</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#166534">İpucu: İki ayrı kelime arasında gerçekleşir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
